function copyKey(e){const t=document.getElementById("generated-key").innerText;navigator.clipboard.writeText(t).then(()=>{e.dataset.originalText||(e.dataset.originalText=e.innerText),e.innerText="Copied!",clearTimeout(e.dataset.timeoutId);const t=setTimeout(()=>{e.innerText=e.dataset.originalText},3e3);e.dataset.timeoutId=t})}